#!/usr/bin/env python3
"""Apply script: speed up Portfolio Analysis Excel ingestion (Members/
Claims uploads) using the calamine engine - roughly halves parse time
on large book-wide exports.

IMPORTANT: after applying, you must also install the new dependency:
    pip install python-calamine
(with your venv activated) before restarting the server.

Run from the HealthCross repo root: python3 apply_calamine_speedup.py
"""
import base64, hashlib, os, sys

MARKER = "CALAMINE_SPEEDUP_2026_08_04"

FILES = [
    {
        'path': 'app/ingestion/portfolio_claims.py',
        'sha256': 'e86b657a906105ef76541ff60f57f3dab66538eaec8cd29697a1f9ec9e5d5b22',
        'size': 4932,
        'b64': '',
    },
    {
        'path': 'app/ingestion/portfolio_members.py',
        'sha256': 'e7b844a8846c45bce31fa0a50d3931d15085e69b8db84d104caedcbe392600a9',
        'size': 4688,
        'b64': '',
    },
    {
        'path': 'requirements.txt',
        'sha256': '3a283c8e1c80d16a118686b29a66aec0c4f8dc4c70c8b1cef43fa7d9b1509b53',
        'size': 241,
        'b64': '',
    },
    {
        'path': 'tests/test_ingestion_portfolio_claims.py',
        'sha256': 'cee4ca25ed940ed74f4fef8111e0c2cb7ad5751e17060accbf2996215faea032',
        'size': 3265,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("\nIMPORTANT NEXT STEP: pip install python-calamine   (with your venv active)")
        print("Then: python3 -m pytest -q   (should show 447 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
